/**
 * إطار التطبيق المقفول — القضاء النهائي على أي تداخل أو كسر عند التكبير:
 *  · الشاشة = h-screen ثابتة (overflow-hidden) — الصفحة نفسها لا تتمرر أبداً
 *  · الشريط الجانبي: عمود ثابت بارتفاع الشاشة (لا sticky ولا fixed على الدسكتوب)
 *  · الهيدر: ثابت أعلى العمود (لا يبتعد عن العين أبداً)
 *  · منطقة المحتوى الوحيدة المسموح لها بالتمرر (overflow-y-auto) بمحتوى محصور العرض
 * التكبير/التصغير لا يكسر البنية: إما وضع دسكتوب الصلب أو وضع درج الموبايل الصلب.
 *
 * الموبايل (<lg):
 *  · درج تنقل منزلق (mobileNavOpen) + خلفية معتمة
 *  · شريط تنقل سفلي ثابت (MobileBottomNav) للوصول السريع بيد واحدة
 *  · حشو سفلي للمحتوى يحترم شريط النظام (safe-area-inset)
 */
import { useEffect } from 'react'
import { Navigate, Outlet, useLocation } from 'react-router'
import clsx from 'clsx'
import { PORTALS, type PortalId } from '@lib/constants/portals.constants'
import { portalThemes } from '@config/portals.config'
import { useUiStore } from '@stores/ui.store'
import { Toaster } from '@components/ui'
import { ActivityReminderBanner } from '@components/feedback/ActivityReminderBanner'
import { InstallBanner } from '@features/pwa/PwaBanners'
import { Sidebar, SidebarBackdrop } from '@components/layout/Sidebar/Sidebar'
import { MobileBottomNav } from '@components/layout/MobileBottomNav'
import { SupportFab } from '@components/layout/SupportFab'
import { Header } from '@components/layout/Header/Header'
import { loadMyHiddenUnits } from '@features/portal-visibility'
import { loadMyPermissions, routeAllowed, useMyPermissionsStore } from '@features/permissions/my-permissions'
import { loadMyManualActivations } from '@features/attendance-manual/store'
import { useAuth } from '@features/auth/hooks/useAuth'
import { useRevokedSessionWatch } from '@features/auth/hooks/useRevokedSessionWatch'
import { SessionTimeout } from '@components/auth/SessionTimeout'

export interface AppShellProps {
  portal: PortalId
}

/** حد شاشات الموبايل/التابليت (مطابق لـ lg في Tailwind = 1024px) */
const MOBILE_MAX_WIDTH = 1024

export function AppShell({ portal }: AppShellProps) {
  const location = useLocation()
  const mobileNavOpen = useUiStore((s) => s.mobileNavOpen)
  const sidebarCollapsed = useUiStore((s) => s.sidebarCollapsed)
  const setMobileNav = useUiStore((s) => s.setMobileNav)
  const fullBleed = useUiStore((s) => s.contentFullBleed)
  const theme = portalThemes[portal]

  // وحدات مخفية لهذا الحساب (تحددها التطوير المركزية) — تحميل مرة واحدة
  useEffect(() => { void loadMyHiddenUnits() }, [])

  // 00350-B: صلاحياتي الفعلية — تُحمَّل مرة لكل مستخدم؛ المسار الممنوع ⇒ 403 (الخادم يرفض الكتابة على أي حال)
  const { data: session } = useAuth()
  const userId = session?.id ?? null
  // ٣-ج: إن أُنهيت جلستي من جهاز آخر أُخرج فوراً بدل انتظار انتهاء رمز الوصول (ساعة)
  useRevokedSessionWatch(userId)
  useEffect(() => { if (userId) void loadMyPermissions(userId) }, [userId])
  // الحضور اليدوي: تفعيلاتي — تحدد ظهور وحدته في الشريط (تُحدَّث كل 5 دقائق وعند العودة للتبويب كي يظهر التفعيل الجديد بلا إعادة دخول)
  useEffect(() => {
    if (!userId) return
    void loadMyManualActivations(true)
    const refresh = (): void => { if (document.visibilityState === 'visible') void loadMyManualActivations(true) }
    const timer = window.setInterval(refresh, 5 * 60_000)
    document.addEventListener('visibilitychange', refresh)
    return () => { window.clearInterval(timer); document.removeEventListener('visibilitychange', refresh) }
  }, [userId])
  const perms = useMyPermissionsStore((s) => (s.userId === userId ? s.perms : null))
  const allowed = routeAllowed(location.pathname, perms)

  // الموبايل: الدرج مغلق افتراضياً — ويُغلق تلقائياً عند تجاوز حد الدسكتوب
  useEffect(() => {
    const sync = (): void => {
      if (window.innerWidth >= MOBILE_MAX_WIDTH) setMobileNav(false)
    }
    // ضبط ابتدائي (في حال فُتح التطبيق لأول مرة على شاشة صغيرة)
    if (window.innerWidth < MOBILE_MAX_WIDTH) setMobileNav(false)
    window.addEventListener('resize', sync)
    return () => window.removeEventListener('resize', sync)
  }, [setMobileNav])

  // التنقل من البحث أو الرجوع/التقدم في المتصفح لا يترك درجاً يحجب الصفحة الجديدة.
  useEffect(() => {
    setMobileNav(false)
  }, [location.pathname, setMobileNav])

  // 00413: قفل الخمول (30 دقيقة) للبوابات الحساسة فقط — المالية و/admin
  const idleLock = portal === PORTALS.FINANCE || portal === PORTALS.ADMIN

  if (!allowed) return <Navigate to="/403" replace />

  return (
    <div className={clsx(theme.themeClass, 'portal-shell relative isolate flex h-full min-h-0 w-full gap-2 overflow-hidden pt-[env(safe-area-inset-top)]')}>
      {/* 00413: قفل الخمول — لا يرسم شيئًا إلا في البوابتين الحسّاستين (المالية · /admin) */}
      <SessionTimeout enabled={idleLock} />
      <a href="#app-main-content" className="fixed start-3 top-3 z-[100] -translate-y-20 rounded-xl bg-slate-950 px-4 py-2 text-sm font-bold text-white shadow-xl transition-transform focus:translate-y-0">تجاوز التنقل إلى المحتوى</a>
      {/* ── الشريط: طبقة مستقلة لا يمكن لمحتوى الصفحات تجاوزها ── */}
      <div className={clsx('relative z-30 h-full flex-none max-lg:hidden', sidebarCollapsed ? 'w-20' : 'w-72')} data-testid="desktop-sidebar-slot">
        <Sidebar portal={portal} variant="desktop" />
      </div>

      {/* ── درج الموبايل (موبايل فقط) ── */}
      {mobileNavOpen && (
        <div className="lg:hidden">
          <Sidebar portal={portal} variant="mobile" onNavigate={() => setMobileNav(false)} />
          <SidebarBackdrop onClose={() => setMobileNav(false)} />
        </div>
      )}

      {/* ── عمود المحتوى: ثابت الارتفاع، التمرير داخلي فقط ── */}
      <div className="relative z-0 flex h-full min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
        <InstallBanner />
        {/* 00417: تذكير كل 30 يومًا — يظهر التذكير الأمني غير المقروء أعلى المحتوى */}
        <ActivityReminderBanner />
        <Header portal={portal} />
        <main
          id="app-main-content"
          tabIndex={-1}
          data-testid="app-main"
          className={clsx(
            'min-w-0 flex-1',
            fullBleed
              ? 'flex min-h-0 flex-col overflow-hidden p-0'
              : // حشو سفلي على الموبايل لتفادي تغطية الشريط السفلي (~64px) + شريط النظام
                'min-h-0 scroll-smooth overflow-x-hidden overflow-y-auto overscroll-y-contain p-4 pb-[calc(5.5rem+env(safe-area-inset-bottom))] outline-none sm:p-6 sm:pb-[calc(5.5rem+env(safe-area-inset-bottom))] lg:[scrollbar-gutter:stable] lg:pb-6',
          )}
        >
          {fullBleed ? (
            <div className="flex min-h-0 flex-1 flex-col">
              <Outlet />
            </div>
          ) : (
            <div className="mx-auto min-h-full w-full max-w-7xl">
              <Outlet />
            </div>
          )}
        </main>

        {/* ── شريط التنقل السفلي — موبايل فقط ── */}
        {!fullBleed && <MobileBottomNav portal={portal} />}
      </div>

      {/* الجولة ٥: الدعم الفني في كل البوابات */}
      <SupportFab portal={portal} />
      <Toaster />
    </div>
  )
}
